def calculate_k(task_1):
    return task_1.G_i / task_1.period

def calculate_nu_i_j(segment, D_i_j):
    return segment.C_i_j / D_i_j

def calculate_U_Tot_j(task_set, j):
    total_util = 0
    for task in task_set:
        if j < len(task.segments):
            total_util += task.segments[j].C_i_j / task.period
    return total_util

def check_rms_compatibility_theorem2(task_set):
    tau_1ss = task_set[0]

    R_1_min = tau_1ss.C_i + tau_1ss.G_i
    L_1 = tau_1ss.period - R_1_min

    for i in range(1, len(task_set)): # Iterate through non-suspending tasks (tau_2 to tau_n)
        tau_i = task_set[i]
        # Assuming tau_i.C_i is the WCET of the non-suspending task
        if not (R_1_min < tau_i.C_i and tau_i.C_i <= L_1):
            return False

    return True

def calculate_segment_response_time(segment_params):
    # segment_params: SegmentParameters object for tau_i_s
    segment_params.R_s = segment_params.phi_s_minus_1 + segment_params.w_s

def calculate_n_jobs_case1(
    w_i_s, phi_j_s_double_prime_minus_1, phi_j_s_prime_minus_1, T_j
):
    # s_double_prime >= s_prime
    delta_phi = phi_j_s_double_prime_minus_1 - phi_j_s_prime_minus_1
    window_for_interference = w_i_s - delta_phi
    if window_for_interference <= 0:
        return 0
    return ceil(window_for_interference / T_j)

def calculate_n_jobs_case2(
    w_i_s, T_j, phi_j_s_prime_minus_1, phi_j_s_double_prime_minus_1
):
    # s_double_prime <= s_prime - 1
    delta_phi = phi_j_s_prime_minus_1 - phi_j_s_double_prime_minus_1
    effective_start_offset = T_j - delta_phi
    window_for_interference = w_i_s - effective_start_offset
    if window_for_interference <= 0:
        return 0
    return ceil(window_for_interference / T_j)
